-- Ticket75F.1: observational v2 lifecycle evidence. This table is not a
-- source of delivery, action, policy, or completion authority.
CREATE TABLE public.v2_lifecycle_diagnostic_events (
  event_key text PRIMARY KEY CHECK (event_key ~ '^v2d-[0-9a-f]{64}$'),
  contract_version text NOT NULL CHECK (contract_version = 'ticket-75f1-v1'),
  invocation_identity text NOT NULL CHECK (invocation_identity ~ '^cti-[0-9a-f]{64}$'),
  turn_id text NULL CHECK (turn_id IS NULL OR turn_id ~ '^v2t-[0-9a-f-]{36}$'),
  claim_attempt_id text NULL CHECK (claim_attempt_id IS NULL OR claim_attempt_id ~ '^[A-Za-z0-9._:-]{1,128}$'),
  workflow_execution_id text NULL CHECK (workflow_execution_id IS NULL OR workflow_execution_id ~ '^[A-Za-z0-9._:-]{1,128}$'),
  canonical_inbound_message_id uuid NULL,
  session_correlation text NULL CHECK (session_correlation IS NULL OR session_correlation ~ '^psn-[0-9a-f]{24}$'),
  route_mode text NULL CHECK (route_mode IS NULL OR route_mode IN ('legacy','shadow','live')),
  route_generation text NULL CHECK (route_generation IS NULL OR route_generation ~ '^[A-Za-z0-9._:-]{1,64}$'),
  lifecycle_stage text NOT NULL CHECK (lifecycle_stage IN ('claim','route','invocation','context','interpretation','resolution','guidance_resolution','guidance_assessment','artifact_assessment','planning','action_execution','final_composer_input','composer','final_gate','reservation','transport','completion','reconciliation')),
  lifecycle_status text NOT NULL CHECK (lifecycle_status IN ('started','selected','completed','eligible','ineligible','blocked','failed','ambiguous','not_executed','handed_off','accepted','reconciliation_required')),
  failure_stage text NULL CHECK (failure_stage IS NULL OR failure_stage IN ('entry','claim_verification','authority','context','interpretation','resolution','guidance_resolution','guidance_assessment','artifact_assessment','planning','action_execution','final_composer_input','composer','final_gate','runtime','deadline','reservation','transport','completion','reconciliation')),
  failure_code text NULL CHECK (failure_code IS NULL OR failure_code IN ('unauthenticated','forbidden_route','malformed_request','claim_not_owned','claim_expired','already_has_reply','context_invalid','authority_unavailable','authority_unresolved','action_lifecycle_unavailable','reservation_precondition_failed','deadline_exceeded','internal_unclassified','runtime_not_configured','response_ineligible','interpretation_failed','resolution_failed','guidance_resolution_failed','guidance_assessment_unavailable','artifact_assessment_unavailable','planning_failed','action_execution_unavailable','final_composer_input_failed','composer_unavailable','final_response_assessment_unavailable','final_response_blocked','final_response_binding_invalid','reservation_unavailable','reservation_conflict')),
  retry_class text NULL CHECK (retry_class IS NULL OR retry_class IN ('none','transient_same_identity','ambiguous_no_blind_retry','operator_required')),
  latency_ms integer NULL CHECK (latency_ms IS NULL OR latency_ms BETWEEN 0 AND 120000),
  stage_trace jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(stage_trace) = 'array' AND jsonb_array_length(stage_trace) <= 16),
  gate_projection jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(gate_projection) = 'object'),
  action_projection jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(action_projection) = 'array' AND jsonb_array_length(action_projection) <= 1),
  reservation_projection jsonb NULL CHECK (reservation_projection IS NULL OR jsonb_typeof(reservation_projection) = 'object'),
  provider_outcome text NULL CHECK (provider_outcome IS NULL OR provider_outcome IN ('accepted','rejected','ambiguous','reconciliation_required')),
  completion_outcome text NULL CHECK (completion_outcome IS NULL OR completion_outcome IN ('completed','pending','reconciliation_required','failed')),
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.v2_lifecycle_diagnostic_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v2_lifecycle_diagnostic_events FORCE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.v2_lifecycle_diagnostic_events FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.record_v2_lifecycle_diagnostic(p jsonb)
RETURNS TABLE(state text, event_key text)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO pg_catalog, public
AS $$
DECLARE e public.v2_lifecycle_diagnostic_events%ROWTYPE; existing public.v2_lifecycle_diagnostic_events%ROWTYPE;
DECLARE allowed text[] := ARRAY['contract_version','event_key','invocation_identity','turn_id','claim_attempt_id','workflow_execution_id','canonical_inbound_message_id','session_correlation','route_mode','route_generation','lifecycle_stage','lifecycle_status','failure_stage','failure_code','retry_class','latency_ms','stage_trace','gate_projection','action_projection','reservation_projection','provider_outcome','completion_outcome'];
BEGIN
  IF jsonb_typeof(p) <> 'object' OR NOT (p ?& ARRAY['contract_version','event_key','invocation_identity','lifecycle_stage','lifecycle_status']) OR EXISTS (SELECT 1 FROM jsonb_object_keys(p) AS k WHERE NOT (k = ANY(allowed))) THEN RAISE EXCEPTION 'V2_DIAGNOSTIC_INPUT_INVALID'; END IF;
  IF p->>'contract_version' <> 'ticket-75f1-v1' OR p->>'event_key' !~ '^v2d-[0-9a-f]{64}$' OR p->>'invocation_identity' !~ '^cti-[0-9a-f]{64}$' OR p->>'lifecycle_stage' NOT IN ('claim','route','invocation','context','interpretation','resolution','guidance_resolution','guidance_assessment','artifact_assessment','planning','action_execution','final_composer_input','composer','final_gate','reservation','transport','completion','reconciliation') OR p->>'lifecycle_status' NOT IN ('started','selected','completed','eligible','ineligible','blocked','failed','ambiguous','not_executed','handed_off','accepted','reconciliation_required') THEN RAISE EXCEPTION 'V2_DIAGNOSTIC_INPUT_INVALID'; END IF;
  IF (p ? 'turn_id' AND p->>'turn_id' !~ '^v2t-[0-9a-f-]{36}$') OR (p ? 'claim_attempt_id' AND p->>'claim_attempt_id' !~ '^[A-Za-z0-9._:-]{1,128}$') OR (p ? 'workflow_execution_id' AND p->>'workflow_execution_id' !~ '^[A-Za-z0-9._:-]{1,128}$') OR (p ? 'canonical_inbound_message_id' AND (p->>'canonical_inbound_message_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') OR (p ? 'session_correlation' AND p->>'session_correlation' !~ '^psn-[0-9a-f]{24}$') OR (p ? 'route_mode' AND p->>'route_mode' NOT IN ('legacy','shadow','live')) OR (p ? 'route_generation' AND p->>'route_generation' !~ '^[A-Za-z0-9._:-]{1,64}$') THEN RAISE EXCEPTION 'V2_DIAGNOSTIC_INPUT_INVALID'; END IF;
  IF (p ? 'failure_stage' AND p->>'failure_stage' NOT IN ('entry','claim_verification','authority','context','interpretation','resolution','guidance_resolution','guidance_assessment','artifact_assessment','planning','action_execution','final_composer_input','composer','final_gate','runtime','deadline','reservation','transport','completion','reconciliation')) OR (p ? 'failure_code' AND p->>'failure_code' NOT IN ('unauthenticated','forbidden_route','malformed_request','claim_not_owned','claim_expired','already_has_reply','context_invalid','authority_unavailable','authority_unresolved','action_lifecycle_unavailable','reservation_precondition_failed','deadline_exceeded','internal_unclassified','runtime_not_configured','response_ineligible','interpretation_failed','resolution_failed','guidance_resolution_failed','guidance_assessment_unavailable','artifact_assessment_unavailable','planning_failed','action_execution_unavailable','final_composer_input_failed','composer_unavailable','final_response_assessment_unavailable','final_response_blocked','final_response_binding_invalid','reservation_unavailable','reservation_conflict')) OR (p ? 'retry_class' AND p->>'retry_class' NOT IN ('none','transient_same_identity','ambiguous_no_blind_retry','operator_required')) OR (p ? 'latency_ms' AND (jsonb_typeof(p->'latency_ms') <> 'number' OR (p->>'latency_ms') !~ '^[0-9]{1,6}$' OR (p->>'latency_ms')::integer > 120000)) THEN RAISE EXCEPTION 'V2_DIAGNOSTIC_INPUT_INVALID'; END IF;
  IF (p ? 'stage_trace' AND (jsonb_typeof(p->'stage_trace') <> 'array' OR jsonb_array_length(p->'stage_trace') > 16 OR EXISTS (SELECT 1 FROM jsonb_array_elements(p->'stage_trace') x WHERE jsonb_typeof(x) <> 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(x) key) IS DISTINCT FROM ARRAY['stage','status'] OR x->>'stage' NOT IN ('context','interpretation','resolution','guidance_resolution','guidance_assessment','artifact_assessment','planning','action_execution','final_composer_input','composer','final_gate') OR x->>'status' NOT IN ('completed','failed')))) OR (p ? 'gate_projection' AND (jsonb_typeof(p->'gate_projection') <> 'object' OR EXISTS (SELECT 1 FROM jsonb_object_keys(p->'gate_projection') k WHERE k NOT IN ('guidance_status','artifact_status','final_status','finding_codes')))) OR (p ? 'action_projection' AND (jsonb_typeof(p->'action_projection') <> 'array' OR jsonb_array_length(p->'action_projection') > 1 OR EXISTS (SELECT 1 FROM jsonb_array_elements(p->'action_projection') x WHERE jsonb_typeof(x) <> 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(x) key) IS DISTINCT FROM ARRAY['action_id','action_type','execution_key','execution_status'] OR x->>'action_id' !~ '^act-[0-9a-f]{64}$' OR x->>'execution_key' !~ '^aek-[0-9a-f]{64}$' OR x->>'action_type' NOT IN ('provide_checkout_destination','provide_holding_page_destination') OR x->>'execution_status' NOT IN ('succeeded','failed_retryable','failed_terminal','in_progress','not_executed')))) THEN RAISE EXCEPTION 'V2_DIAGNOSTIC_INPUT_INVALID'; END IF;
  IF p ? 'reservation_projection' THEN
    IF jsonb_typeof(p->'reservation_projection') <> 'object' OR EXISTS (SELECT 1 FROM jsonb_object_keys(p->'reservation_projection') k WHERE k NOT IN ('state','logical_reply_key','part_count','message_ids')) OR p->'reservation_projection'->>'state' NOT IN ('reserved_new','reserved_existing','not_executed') THEN RAISE EXCEPTION 'V2_DIAGNOSTIC_INPUT_INVALID'; END IF;
    IF p->'reservation_projection' ? 'logical_reply_key' AND p->'reservation_projection'->>'logical_reply_key' !~ '^reply:[A-Za-z0-9._:-]{1,256}$' THEN RAISE EXCEPTION 'V2_DIAGNOSTIC_INPUT_INVALID'; END IF;
    IF p->'reservation_projection' ? 'part_count' AND (p->'reservation_projection'->>'part_count') !~ '^[1-9][0-9]{0,2}$' THEN RAISE EXCEPTION 'V2_DIAGNOSTIC_INPUT_INVALID'; END IF;
    IF p->'reservation_projection' ? 'message_ids' AND (jsonb_typeof(p->'reservation_projection'->'message_ids') <> 'array' OR jsonb_array_length(p->'reservation_projection'->'message_ids') > 999 OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(p->'reservation_projection'->'message_ids') x WHERE x !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')) THEN RAISE EXCEPTION 'V2_DIAGNOSTIC_INPUT_INVALID'; END IF;
  END IF;
  IF (p ? 'provider_outcome' AND p->>'provider_outcome' NOT IN ('accepted','rejected','ambiguous','reconciliation_required')) OR (p ? 'completion_outcome' AND p->>'completion_outcome' NOT IN ('completed','pending','reconciliation_required','failed')) THEN RAISE EXCEPTION 'V2_DIAGNOSTIC_INPUT_INVALID'; END IF;
  INSERT INTO public.v2_lifecycle_diagnostic_events(event_key,contract_version,invocation_identity,turn_id,claim_attempt_id,workflow_execution_id,canonical_inbound_message_id,session_correlation,route_mode,route_generation,lifecycle_stage,lifecycle_status,failure_stage,failure_code,retry_class,latency_ms,stage_trace,gate_projection,action_projection,reservation_projection,provider_outcome,completion_outcome)
  VALUES (p->>'event_key',p->>'contract_version',p->>'invocation_identity',NULLIF(p->>'turn_id',''),NULLIF(p->>'claim_attempt_id',''),NULLIF(p->>'workflow_execution_id',''),NULLIF(p->>'canonical_inbound_message_id','')::uuid,NULLIF(p->>'session_correlation',''),NULLIF(p->>'route_mode',''),NULLIF(p->>'route_generation',''),p->>'lifecycle_stage',p->>'lifecycle_status',NULLIF(p->>'failure_stage',''),NULLIF(p->>'failure_code',''),NULLIF(p->>'retry_class',''),NULLIF(p->>'latency_ms','')::integer,COALESCE(p->'stage_trace','[]'::jsonb),COALESCE(p->'gate_projection','{}'::jsonb),COALESCE(p->'action_projection','[]'::jsonb),p->'reservation_projection',NULLIF(p->>'provider_outcome',''),NULLIF(p->>'completion_outcome',''))
  ON CONFLICT ON CONSTRAINT v2_lifecycle_diagnostic_events_pkey DO NOTHING RETURNING * INTO e;
  IF e.event_key IS NOT NULL THEN RETURN QUERY SELECT 'recorded'::text, e.event_key; RETURN; END IF;
  SELECT * INTO existing FROM public.v2_lifecycle_diagnostic_events AS d WHERE d.event_key=p->>'event_key';
  IF existing.contract_version IS NOT DISTINCT FROM p->>'contract_version' AND existing.invocation_identity IS NOT DISTINCT FROM p->>'invocation_identity' AND existing.turn_id IS NOT DISTINCT FROM NULLIF(p->>'turn_id','') AND existing.claim_attempt_id IS NOT DISTINCT FROM NULLIF(p->>'claim_attempt_id','') AND existing.workflow_execution_id IS NOT DISTINCT FROM NULLIF(p->>'workflow_execution_id','') AND existing.canonical_inbound_message_id IS NOT DISTINCT FROM NULLIF(p->>'canonical_inbound_message_id','')::uuid AND existing.session_correlation IS NOT DISTINCT FROM NULLIF(p->>'session_correlation','') AND existing.route_mode IS NOT DISTINCT FROM NULLIF(p->>'route_mode','') AND existing.route_generation IS NOT DISTINCT FROM NULLIF(p->>'route_generation','') AND existing.lifecycle_stage IS NOT DISTINCT FROM p->>'lifecycle_stage' AND existing.lifecycle_status IS NOT DISTINCT FROM p->>'lifecycle_status' AND existing.failure_stage IS NOT DISTINCT FROM NULLIF(p->>'failure_stage','') AND existing.failure_code IS NOT DISTINCT FROM NULLIF(p->>'failure_code','') AND existing.retry_class IS NOT DISTINCT FROM NULLIF(p->>'retry_class','') AND existing.latency_ms IS NOT DISTINCT FROM NULLIF(p->>'latency_ms','')::integer AND existing.stage_trace IS NOT DISTINCT FROM COALESCE(p->'stage_trace','[]'::jsonb) AND existing.gate_projection IS NOT DISTINCT FROM COALESCE(p->'gate_projection','{}'::jsonb) AND existing.action_projection IS NOT DISTINCT FROM COALESCE(p->'action_projection','[]'::jsonb) AND existing.reservation_projection IS NOT DISTINCT FROM p->'reservation_projection' AND existing.provider_outcome IS NOT DISTINCT FROM NULLIF(p->>'provider_outcome','') AND existing.completion_outcome IS NOT DISTINCT FROM NULLIF(p->>'completion_outcome','') THEN RETURN QUERY SELECT 'recorded_existing'::text, existing.event_key; RETURN; END IF;
  RAISE EXCEPTION 'V2_DIAGNOSTIC_EVENT_CONFLICT';
END $$;

REVOKE ALL ON FUNCTION public.record_v2_lifecycle_diagnostic(jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.record_v2_lifecycle_diagnostic(jsonb) TO service_role;
COMMENT ON TABLE public.v2_lifecycle_diagnostic_events IS 'Ticket75F.1 backend-only observational v2 diagnostics; never authoritative business state.';
COMMENT ON FUNCTION public.record_v2_lifecycle_diagnostic(jsonb) IS 'Ticket75F.1 closed append-only diagnostic recorder; rejects prose, payloads, destinations, credentials and unknown fields.';
